// Comprobación local del respaldo; no accede a la base de datos de producción.
import {createServer} from 'node:http';import{DatabaseSync}from'node:sqlite';import{existsSync}from'node:fs';import{readFile,mkdir,copyFile}from'node:fs/promises';import{fileURLToPath}from'node:url';import{resolve,extname,dirname}from'node:path';
import{handleMarketRequest}from'./fuente/server/market.mjs';
const baseDir=dirname(fileURLToPath(import.meta.url)),root=resolve(baseDir,'fuente/dist'),state=resolve(baseDir,'estado-local');await mkdir(state,{recursive:true});const file=resolve(state,'produccion.sqlite');if(!existsSync(file))await copyFile(resolve(baseDir,'datos/produccion.sqlite'),file);const raw=new DatabaseSync(file);raw.exec('PRAGMA foreign_keys=ON');
const prepare=sql=>{const statement=raw.prepare(sql);let parameters=[];const args=()=>parameters.map(v=>v instanceof ArrayBuffer?Buffer.from(v):v);const query={bind(...values){parameters=values;return query;},async first(){return statement.get(...args())||null;},async all(){return{results:statement.all(...args())};},async run(){return{meta:{changes:Number(statement.run(...args()).changes)}};}};return query;};const db={prepare,async batch(items){raw.exec('BEGIN');try{for(const item of items)await item.run();raw.exec('COMMIT');}catch(error){raw.exec('ROLLBACK');throw error;}}};
const mime={'.html':'text/html; charset=utf-8','.css':'text/css','.js':'text/javascript','.mjs':'text/javascript','.json':'application/json','.jpg':'image/jpeg','.jpeg':'image/jpeg','.png':'image/png','.svg':'image/svg+xml','.mp3':'audio/mpeg','.hdr':'application/octet-stream'};
const server=createServer(async(req,res)=>{try{const url=new URL(req.url,'http://localhost:8788');if(url.pathname.startsWith('/api/')){const parts=[];let size=0;for await(const part of req){size+=part.length;if(size>4*1024*1024){res.writeHead(413);res.end();return;}parts.push(part);}const body=Buffer.concat(parts),response=await handleMarketRequest(new Request(url,{method:req.method,headers:req.headers,...(body.length?{body}:{} )}),{MARKET_DB:db});res.writeHead(response.status,Object.fromEntries(response.headers));res.end(Buffer.from(await response.arrayBuffer()));return;}const file=resolve(root,'.'+decodeURIComponent(url.pathname==='/'?'/index.html':url.pathname));if(!file.startsWith(root+'/')){res.writeHead(403);res.end();return;}const bytes=await readFile(file);res.writeHead(200,{'Content-Type':mime[extname(file)]||'application/octet-stream'});res.end(bytes);}catch{res.writeHead(404);res.end('No disponible');}});server.listen(8788,'127.0.0.1',()=>console.log('Copia local disponible en http://localhost:8788. Producción no se modifica.'));
